//! Spark (REV Robotics) CAN frame decoding: a port of
//! `src/hub/dataSources/schema/spark/` from upstream AdvantageScope.
//! `tables` is generated by `cargo xtask tables spark`.

mod bignum;
mod bitstring;
mod can_spec;
pub mod tables;

pub use bignum::BigNum;
pub use can_spec::{
    Frame, FrameKind, ParsedCanFrame, Signal, SignalType, SignalValue, get_can_signal_value,
    parse_can_frame,
};

/// Any `Error` thrown by the upstream port sites; `message` is the thrown text.
#[derive(Debug)]
pub struct SparkError(pub String);

impl std::fmt::Display for SparkError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

impl std::error::Error for SparkError {}
